{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket encryption not configured",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'financials' does not have server-side encryption enabled. Data at rest is unencrypted, violating security best practices for sensitive financial data."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block missing",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "There is no aws_s3_bucket_public_access_block resource associated with this bucket. Without it, the bucket relies on default account settings which may allow public access if misconfigured elsewhere."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Access Logging disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for the bucket. This prevents auditing of who accessed the financial data and when."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Versioning disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled. Accidental deletion or overwriting of financial documents cannot be recovered."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket                  = aws_s3_bucket.financials.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "financials" {
  bucket = aws_s3_bucket.financials.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "financials" {
  bucket        = aws_s3_bucket.financials.id
  target_bucket = aws_s3_bucket.log_bucket.id # Assumes a log bucket exists; replace with actual log bucket ID
  target_prefix = "log/"
}",
  "fix_summary": "Added server-side encryption configuration (AES256), public access block, versioning, and access logging to the 'financials' S3 bucket to remediate security findings CKV_AWS_145, CKV2_AWS_6, CKV_AWS_21, and CKV_AWS_18 respectively. Note: The logging configuration references a placeholder 'aws_s3_bucket.log_bucket' which must exist in your state or be replaced with a valid bucket ID."
}
